package cn.courselens;
import android.content.*;import android.provider.*;import org.json.*;import org.junit.Test;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.Config;import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=34)
public class AiPhoneActionsTest {
 @Test public void nativeActionsPreserveSystemReviewAndNeverDirectCall()throws Exception{Context c=RuntimeEnvironment.getApplication();Intent alarm=AiPhoneActions.intent(c,new JSONObject("{action:set_alarm,hour:8,minute:30}"));assertEquals(AlarmClock.ACTION_SET_ALARM,alarm.getAction());assertEquals(30,alarm.getIntExtra(AlarmClock.EXTRA_MINUTES,-1));assertFalse(alarm.getBooleanExtra(AlarmClock.EXTRA_SKIP_UI,true));Intent dial=AiPhoneActions.intent(c,new JSONObject("{action:dial,number:'10086'}"));assertEquals(Intent.ACTION_DIAL,dial.getAction());assertEquals("tel:10086",dial.getDataString());Intent timer=AiPhoneActions.intent(c,new JSONObject("{action:set_timer,seconds:60}"));assertEquals(60,timer.getIntExtra(AlarmClock.EXTRA_LENGTH,0));assertFalse(timer.getBooleanExtra(AlarmClock.EXTRA_SKIP_UI,true));}
 @Test public void invalidAndUnexpectedFieldsAreRejected()throws Exception{for(String raw:new String[]{"{action:set_volume,percent:101}","{action:set_alarm,hour:24,minute:0}","{action:set_timer,seconds:0}","{action:dial,number:'*21#'}","{action:open_settings,setting:arbitrary}","{action:launch_app,app:Example,url:evil}"}){assertThrows(Exception.class,()->AiPhoneActions.describe(new JSONObject(raw)));}}
 @Test public void missingAppDoesNotFallBackToArbitraryIntent()throws Exception{assertThrows(Exception.class,()->AiPhoneActions.intent(RuntimeEnvironment.getApplication(),new JSONObject("{action:launch_app,app:'missing.synthetic.app'}")));}
}
